from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.models import Payment
from ledgerly.payments import capture_partial
from ledgerly.errors import BillingError
from ledgerly import audit

T0 = datetime(2026,1,1,tzinfo=timezone.utc)
def mk(): return Payment("p","i",Decimal("100.00"),created_at=T0)

p=mk(); capture_partial(p, Decimal("60.005"), T0); print("round:", p.amount, p.status, p.captured_at)
for amt in [Decimal("0"), Decimal("-1"), Decimal("100.01")]:
    try: capture_partial(mk(), amt, T0)
    except BillingError as e: print("err", amt, e.code)
try: capture_partial(mk(), Decimal("1"), datetime(2026,1,1))
except BillingError as e: print("naive:", e.code)
p=mk(); p.status="captured"
try: capture_partial(p, Decimal("1"), T0)
except BillingError as e: print("state:", e.code)
p=mk(); r1=capture_partial(p, Decimal("10"), T0, idempotency_key="k1"); r2=capture_partial(p, Decimal("10"), T0, idempotency_key="k1")
print("idem same:", r1 is r2, len(audit.events("payment_captured")))
EOF"}

